terraform {
  backend "s3" {
    bucket         = "my-bucket"
    key            = "path/to/my/key"
    region         = "us-east-1"
    encrypt        = true
    kms_key_id     = "my-kms-key-id"
    dynamodb_table = "my-lock-table"
  }
}

validation {
  condition     = can(regex("^ami-", var.image_id))
  error_message = "The image_id value must start with \"ami-\"."
}

lifecycle {
  create_before_destroy = true
  prevent_destroy       = true
  ignore_changes        = [tags]
  replace_triggered_by  = [aws_launch_template.foo]
}

dynamic "ingress" {
  for_each = var.ingress_rules
  content {
    from_port = ingress.value.from
    to_port   = ingress.value.to
    protocol  = "tcp"
  }
}

variable "obj" {
  type = object({
    name = string
    port = optional(number, 80)
  })
}

policy = jsonencode({
  Version = "2012-10-17"
  Statement = [{
    Action   = "s3:ListBucket"
    Effect   = "Allow"
    Resource = "*"
  }]
})

locals {
  common_tags = {
    Environment = var.env
    Team        = var.team
    ManagedBy   = "terraform"
  }
}
